-- 0292 misterio: sitios concretos (reparseado del .pages, 262 sitios/202 munis)
DELETE FROM entidades WHERE fuente='inventario_misterioso_pdf';
DELETE FROM puntuaciones WHERE categoria='misterioso';
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12080','misterio','Misterios de Morella','Conocida como la "puerta de los magos". Famosa por sus procesiones de brujas en la Edad Media y por el linaje de los "Blanes". El convento de San Francisco tiene leyendas de apariciones de monjas y fenómenos paranormales.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46250','misterio','Misterios de Valencia','El misterio de la calle Dalt. Leyendas de la Inquisición, callejones oscuros con apariciones de antiguos reos, y las historias de brujería en la huerta valenciana (como la "bruixa" de Patraix).','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08003','misterio','Misterios de Barcelona','El Cementerio de Montjuïc es un epicentro de paranormal y espiritismo. En el Barrio Gótico se reportan apariciones en el antiguo barrio judío y en el Palau Reial Major. Leyendas de la "Casa de l''Ardiaca".','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08003','misterio','Cementerio de Poblenou','Uno de los cementerios con más actividad paranormal de España. Cuenta con la leyenda de su propio "vampiro" y del fantasma de Don Rosendo de Vicente y Vicente, cuya tumba aparece frecuentemente adornada con flores frescas de origen desconocido. Es parada habitual de rutas de misterio.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08003','misterio','Cementerio de Montjuïc','Es el epicentro del espiritismo barcelonés. Numerosos investigadores paranormales han captado psicofonías y reportado apariciones entre sus mausoleos, especialmente en las zonas más antiguas.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08003','misterio','Hospital de la Santa Creu i Sant Pau','Se reporta el fantasma del arquitecto Antoni Gaudí (que falleció atropellado en 1926 tras ser atropellado cerca del recinto) y apariciones de monjas y antiguos pacientes. El claustro del Raval, sede original, es lugar de avistamientos frecuentes.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50265','misterio','Misterios de Trasmoz','Único pueblo de España oficialmente excomulgado por la Iglesia (hasta 1998). Cuna de la brujería aragonesa. El castillo, en ruinas, es visitable y centro de rituales paganos y avistamientos de luces inexplicables. Escenario de la leyenda de la Campana de Velilla.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50045','misterio','Misterios de Belchite','Turismo oscuro y parapsicología. Escenario de una de las batallas más crueles de la Guerra Civil. Visitable mediante tours guiados. Fenómenos de psicofonía, voces, pasos y apariciones de soldados caídos.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31264','misterio','Misterios de Zugarramurdi','Capital española de la brujería. Origen del famoso auto de fe de Logroño (1610). Las cuevas son completamente visitables y se celebran akelarres modernos. Fuerte energía telúrica y turismo esotérico masivo.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('21014','misterio','Misterios de Oñati','Aparición de la Virgen a un pastor en un espino (leyenda fundacional). Conexión con antiguos cultos paganos vascos (Sorginak) y la mitología de basajaun y lamias en las cuevas de la zona.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24115','misterio','Misterios de Ponferrada','Enigma templario por excelencia. Conexión con el río Sil y la zona de la "Guerra de los Magos". Se investigan rituales de alquimia y símbolos ocultos en la mampostería del castillo.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42164','misterio','Misterios de San Leonardo de Yagüe','Soria es la cuna de las leyendas de Gustavo Adolfo Bécquer ("Los ojos verdes", "El rayo de luna"). La zona de la Sierra de Urbión está plagada de leyendas de las "xanas", súcubos y aparecidos en las lagunas glaciares.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37011','misterio','Misterios de Salamanca','La Cueva de Salamanca es el lugar donde según la leyenda el diablo enseñaba magia negra a 7 alumnos (quedando uno como pago). Punto de peregrinación esotérica y turismo de brujería y nigromancia.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('51025','misterio','Misterios de Ávila','Centro místico de España. Misticismo extremo, levitaciones (Santa Teresa de Jesús), y apariciones en el casco antiguo amurallado. Conexión con la Orden del Temple.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45053','misterio','Misterios de Consuegra','Castillo templario con evidentes símbolos esotéricos. Leyendas de tesoros escondidos y apariciones de caballeros caídos en reconquistas.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19053','misterio','Misterios de Brihuega','La "Cueva de la Hiedra" es famosa por rituales de brujería. El municipio es conocido por su historia de aquíes y el conocimiento de los ciclos astrales desde tiempos celtas y romanos.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28079','misterio','Misterios de Madrid','El Palacio de Linares es la casa encantada más famosa de España (apariciones de la hija asesinada). La Estación de Chamberí ("Estación fantasma") ofrece tours de fenómenos paranormales. El cementerio de la Almudena tiene alta actividad espiritista.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28079','misterio','Casa de las Siete Chimeneas','Una de las casas encantadas más famosas de Madrid. Cuenta la leyenda que el fantasma de Elena, amante de Felipe II, se aparece de blanco en el tejado dándose golpes en el pecho. Otra versión habla de una novia muerta el día de su boda.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28079','misterio','Estación de Chamberí','Cerrada en 1966, durante décadas los trenes pasaban sin detenerse alimentando el mito urbano. Hoy se pueden visitar sus instalaciones originales y es parada de rutas de misterio.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28079','misterio','Palacio de Linares','La leyenda de Raimundita, la niña asesinada por los marqueses al descubrir su incesto, es una de las historias paranormales más conocidas de España. Se han grabado psicofonías y son frecuentes los reportes de apariciones.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28079','misterio','Edificio Telefónica (Gran Vía 28)','El fantasma "Goyito", un niño que vaga por las plantas 9 y 13 (donde estaba la biblioteca). Los empleados reportan su aparición desde hace décadas. Ligado también a la historia de Ana Cubillo.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28079','misterio','El Baúl del Monje','Uno de los poltergeist más famosos de España, investigado por el Grupo Hepta y la periodista Cristina Rovirosa en 1999. Objetos que saltaban por el aire, vasos que estallaban solos, lámparas que se movían, grifos que se abrían, olores cambiantes. Intervino la Policía Científica.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28079','misterio','Palacio de Liria','Considerado "embrujado" por un fantasma. La duquesa Cayetana de Alba siempre reconoció la presencia. El palacio sufrió daños en la Guerra Civil, lo que aumentó las leyendas.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28079','misterio','Museo de Cera','Investigado por el programa Casafantasmas. Se reportan fenómenos paranormales y psicofonías en distintas salas, especialmente nocturnas.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28079','misterio','Cementerio de la Almudena','Rutas específicas guiadas ("Leyendas de la Almudena"). Se narran leyendas como la del "Ángel Exterminador" (Fausto), los enterradores fantasmas y los "pasajeros fantasmas del autobús de la línea 110".','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28038','misterio','Misterios de Cercedilla','La "Casa de la Mora" es un hotel y restaurante famoso por las apariciones de una mujer y soldados de la Guerra Civil. Muy popular entre los investigadores paranormales de Madrid.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10037','misterio','Misterios de Cáceres','Declarado Patrimonio de la Humanidad, su casco antiguo es un laberinto medieval. Reportes de apariciones en la Plaza de San Jorge, sonidos de cadenas en casas solariegas y fuerte huella de la Inquisición y la Orden de Santiago.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10037','misterio','Carreteras paranormales','Concentración notable de apariciones en cunetas: el hombre alto vestido de negro de la curva de Mirabel; la Dama Blanca que aparece sentada en noches de tormenta en la carretera Casar de Cáceres-Arroyo de la Luz; la joven de la recta Montehermoso-Pozuelo de Zarzón; la dama de rojo de Miajadas; la niña de comunión en la carretera de Peraleda de la Mata; "La Portuguesa".','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10087','misterio','Misterios de Guadalupe','La leyenda del hallazgo de la virgen por un pastor y la aparición de la virgen. Conexión templaria en la zona y misticismo de los caballeros ocultos en el monasterio.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41091','misterio','Misterios de Sevilla','La Casa de las Cabezas es parada obligatoria de terror histórico. El convento de Santa Clara tiene leyendas de monjas emparedadas. Actividad paranormal reportada en el Cementerio de San Fernando.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41091','misterio','Casa del mayoral / Finca de Bertín Osborne','Bertín Osborne ha confesado públicamente vivir con un fantasma en su finca sevillana. Un equipo de parapsicología captó presencias con cámaras térmicas, detectores y psicoimágenes que se retransmitieron en El Show de Bertín. La actividad se centra en la estancia sobre la capilla.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41091','misterio','Cementerio de San Fernando','Reportes de actividad espiritista y apariciones. Es parada de las rutas de misterio sevillanas, junto con la Casa de las Cabezas y el Convento de Santa Clara.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18087','misterio','Misterios de Granada','El cementerio de San José (sobre un antiguo cementerio morisco) es uno de los lugares más estudiados por psicofonías. El Albaicín alberga leyendas de duendes y apariciones de la época nazarí.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18087','misterio','Antiguo edificio de la Diputación (calle Mesones)','Uno de los casos de poltergeist más célebres de España. Sobre el solar (mezquita/rábita nazarí) se construyó la parroquia de la Magdalena, "maldita" desde 1651 porque las imágenes se desprendían. En 1971, al derribar un muro, aparecieron restos humanos infantiles. En 1985, ya como Diputación, comenzaron los fenómenos: máquinas de escribir que funcionaban solas, cajones que se abrían, gritos, objetos que se movían, luces proyectadas en las paredes, fotosíntesis invertida de las plantas, alteraciones electromagnéticas, mordeduras y tirones de pelos. En Navidad de 1986 el Grupo Omega, liderado po','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18087','misterio','Real Conservatorio Superior de Música "Victoria Eugenia"','El fantasma de Felipe, antiguo profesor de piano del centro, obligado a dejar la docencia con pena. Notas que suenan solas en el piano (siempre la misma pieza, su favorita, según confirmó el antiguo director), monedas que caen del techo y voces inexplicables en pasillos y aulas vacías. El actual profesor de piano César Requesens (La Granada Insólita y Secreta) lo recopiló; otros profesores han vivido experiencias similares.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18087','misterio','Pub El Granero','Fenómenos paranormales documentados por el diario Ideal. El sótano del pub conserva muros de ladrillo del siglo XVII donde se han producido apariciones y sucesos inexplicables. Investigado por José Manuel García Bautista.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18087','misterio','Antigua sede de la Cruz Roja (Realejo)','Poltergeist documentado por el diario Ideal. Tras la muerte de un voluntario en accidente de tráfico, comenzaron golpes en su taquilla (cerrada con llave), objetos que aparecían fuera de ella, ruido de cristales rompiéndose sin rastro, pasos por los pasillos. Los voluntarios realizaron sesiones de ouija. Recogido por Daniel Maya ("Granada tras la niebla").','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18087','misterio','Hotel Reuma / "Casa de Muñecas"','Edificio centenario envuelto en leyendas de fantasmas y lamentos nocturnos. Se hizo viral en redes sociales. Daniel Maya incluye rutas específicas ("Ecos del Albaicín Bajo") que recorren el edificio y sus alrededores.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18087','misterio','Casa de Castril / Museo Arqueológico','Leyenda de Elvira, la "Dama Blanca". Hija de Hernando de Zafra (nieto), se enamoró de Alfonso de Quintanilla, de linaje enemistado. Encerrada y con el balcón tapiado, se suicidó con veneno. Muchos aseguran que su espíritu vaga por los pasillos del actual museo.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18087','misterio','Casa de la Hornacina / Casa del Miedo (Albaicín)','Una de las "casas del miedo" granadinas. La leyenda resultó ser un engaño del pillo Mascafierro, que fingía sonidos de ultratumba por orden de un magistrado para espantar a los curiosos mientras este se veía con una dama de la casa colindante.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18087','misterio','Alhambra (subterráneos y Torres Bermejas)','Bajo la Alhambra se extiende una red de pasillos, mazmorras y laberintos donde se oyen ruidos misteriosos, voces, silbidos, objetos que se mueven y ecos inexplicables. Apariciones reportadas por muchos visitantes. Leyendas como la de la princesa Zaira, el lobo de la Alhambra en noches de plenilunio, el ciprés de la Sultana (Morayma y los Abencerrajes) y los tesoros ocultos de Boabdil.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18087','misterio','Carmen de los Mártires','Llamado "Campo de Ahabul" por los árabes y "Corral de los Cautivos" por los cristianos. Lugar desde donde Boabdil partió para entregar Granada. Sus jardines "están llenos de misterio" y se reportan extrañas presencias.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18087','misterio','Cementerio de San José','Lleno de mitos y leyendas, apariciones fantasmales y relatos transmitidos de generación en generación. Uno de los enclaves paranormales de la ciudad.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18087','misterio','Barrio del Realejo (ruta)','Daniel Maya ("Granada tras la niebla") recorre sus misterios y casas encantadas. Hay un "colegio fantasma" (Colegio José Hurtado) investigado por Cuarto Milenio y un lado oscuro del Realejo con historias de apariciones.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18087','misterio','Sacromonte','Leyendas negras de tesoros moriscos enterrados en cuevas que "se tragaban" a quienes los buscaban con codicia, desapariciones, luces extrañas y apariciones. La Abadía es uno de los grandes enigmas de Granada.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24010','misterio','Misterios de Baeza','Centro de la magia y nigromancia andaluza durante el Renacimiento. Profundamente ligado a la historia de "El Brujo de Baeza" y apariciones en callejuelas oscuras.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('38023','misterio','Misterios de San Cristóbal de La Laguna','La Laguna es conocida como la "ciudad de los conventos y los aparecidos". La Casa Lercaro es una de las casas encantadas más activas de España (aparición de Catalina Lercaro). Rutas de misterio nocturnas muy concurridas.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('38005','misterio','Misterios de Garachico','Historias de brujería canaria y apariciones de ánimas en pena. La erupción volcánica de 1706 dejó ruinas malditas y un fuerte legado de leyendas locales.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27030','misterio','Misterios de Mondoñedo','Famoso por la Santa Compaña y tradiciones meigas. Se pueden visitar lugares donde ocurrieron supuestos avistamientos de procesiones de difuntos. El turismo místico es parte de su identidad.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('01014','misterio','Misterios de Noia','Conocida como la "ciudad de la brujería" en Galicia. Famosa por sus cementerios antiguos y la fuerte presencia de meigas (brujas) en su historia local documentada y leyendas urbanas.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33044','misterio','Misterios de Oviedo','El misterio de la Cruz de los Ángeles y las apariciones de la "Dama de Blanco" en la Universidad. Fuerte tradición de "xanas" (ninfas de los ríos) en las afueras.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39076','misterio','Misterios de Santillana del Mar','Aunque es un pueblo histórico, sus callejas ocultan leyendas de la Inquisición y casas solariegas con sonidos y presencias (como la Casa del Águila y la Parra). Fuerte turismo esotérico en la zona rural de Cantabria.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24018','misterio','Misterios de Bélmez de la Moraleda','Desde 1971, en la cocina de la casa de María Gómez Cámara empezaron a aparecer —y reaparecer tras ser picadas— manchas con forma de rostros humanos en el suelo de cemento. Es uno de los casos paranormales más famosos del mundo y la casa sigue siendo visitable en el pueblo.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18176','misterio','Misterios de Soportújar','Autodenominado "Pueblo de las Brujas". Tras la expulsión morisca fue repoblado por familias gallegas que trajeron el culto a las meigas. Cada calle tiene su propia historia mágica y se celebra un Festival de Brujería anual.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22006','misterio','Misterios de Ayamonte','Tildado de "pueblo maldito", sus calles han sido escenario de numerosas leyendas, entre ellas la del jinete sombrío que aparece cabalgando las noches de luna llena por la zona alta del pueblo.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22004','misterio','Misterios de Aracena','Existen leyendas locales de "cortijos malditos" y apariciones espectrales en las sierras circundantes, ligadas a un sustrato de brujería rural que sobrevivió hasta el siglo XX.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('21034','misterio','Misterios de Galaroza','Su leyenda fundacional es en sí un misterio: un pastor desaparece misteriosamente y en el lugar donde se le vio por última vez brota un manantial que da origen al pueblo.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('14021','misterio','Misterios de Córdoba','La Facultad de Derecho, construida sobre un antiguo hospital psiquiátrico y correccional, es uno de los edificios con más actividad paranormal de Andalucía (pasos, voces y apariciones). La Judería acumula leyendas de la Inquisición.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('04004','misterio','Misterios de Almería','El Teatro Cervantes guarda la historia de Conchita Robles, actriz asesinada en 1922 cuyas apariciones siguen reportándose. Además, en la provincia existieron dos casos de apariciones marianas y apariciones ligadas al accidente ferroviario de Fiñana en 1943.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22149','misterio','Misterios de Loarre','Según la leyenda, en sus muros falleció el conde Don Julián y está enterrado el "mayor traidor de España". Numerosos visitantes reportan la aparición del fantasma del conde y de doña Violante de Luna, sobrina del Papa Luna, cuya tumba nunca se halló.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44127','misterio','Misterios de Jabaloyas','Una de las "tierras de brujas" más documentadas de la Sierra de Albarracín. La leyenda del pastor y las brujas de Jabaloyas cuenta que descendían volando sobre escobas para robar el vino de las bodegas de Frías de Albarracín.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44109','misterio','Misterios de Frías de Albarracín','Escenario complementario de la leyenda de las brujas de Jabaloyas. La tradición oral mantiene viva la historia del "Tío Candelas" y su bodega vigilada.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('43001','misterio','Misterios de Albarracín','Uno de los pueblos más mágicos de España, con leyendas de apariciones en sus callejuelas, una abundante tradición de brujería en la sierra y un caso documentado de experiencia paranormal en el casco urbano.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09091','misterio','Misterios de Castrojeriz','Vigía del Camino de Santiago desde el siglo IX. Sus murallas acumulan leyendas de prisioneros, nobles y reyes, y son frecuentes las rutas nocturnas de misterio.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42046','misterio','Misterios de Calatañazor','"En Calatañazor perdió Almanzor el tambor". Pueblo detenido en el tiempo donde, según la leyenda, cayó el invencible caudillo musulmán. El ambiente medieval invita a rutas de leyenda.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42094','misterio','Misterios de Garray','En lo alto del cerro de La Muela aún se siente, según los visitantes, "la fuerza de un pueblo que resistió al Imperio Romano". Numancia es un lugar cargado de energía histórica y leyendas de sacrificio colectivo.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42029','misterio','Misterios de Barahona','Considerado durante siglos un foco de brujería, aparece recogido en las crónicas de cazas de brujas de la provincia, junto con otros pueblos sorianos de tradición esotérica.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19127','misterio','Misterios de Galve de Sorbe / Masegoso','La leyenda del fantasma de Masegoso cuenta que el pueblo entero desapareció tras un envenenamiento por envidia. Es uno de los enigmas rurales de Soria.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39037','misterio','Misterios de Liérganes','Cuna de la leyenda del Hombre Pez de Liérganes, el ser mitad hombre mitad pez que, según la tradición del siglo XVIII, fue visto en distintas costas europeas. El pueblo tiene un marcado carácter de leyenda.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39055','misterio','Misterios de Potes','Capital de Liébana, tierra de ojáncanos, anjanas y leyendas de tesoros ocultos. Existe la leyenda de la "Mansión de los Espíritus", una casona habitada por almas perdidas.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39032','misterio','Misterios de Hermandad de Campoo de Suso','El castillo se levantó sobre una ermita del siglo IX y aún conserva una necrópolis en su patio. Existe un sainete teatral tradicional, "El fantasma del Castillo de Argüeso", basado en la traición de Don Fernando de Mier.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90637','misterio','Misterios de Aller','La Casa de los Bayón fue escenario, a comienzos del siglo XX, de uno de los casos de poltergeist más famosos de España, documentado incluso con intervención de la Guardia Civil. Es considerada una de las casas rurales más embrujadas del país.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33053','misterio','Misterios de Quirós','En abril de 1854 todos los habitantes de Mengollo aparecieron muertos sin signos de violencia. Es la "leyenda del pueblo fantasma de Asturias", uno de los enigmas sin resolver de la región.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33062','misterio','Misterios de Santa Eulalia de Oscos','El valle fue, según la leyenda, la prisión donde un hidalgo cumplió cadena perpetua por asesinar al cura del pueblo por orden de su señor. Es una ruta de misterio destacada.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33063','misterio','Misterios de San Tirso de Abres','Según la tradición, la noche de San Juan aparece un hada encantada en la cascada de la Pena do Encanto para hechizar a quien la vea. Una de las rutas mágicas más señaladas de Asturias.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05008','misterio','Misterios de Cudillero','Crónica de brujería marinera: si los marineros se cruzaban con una mujer considerada bruja al salir a faenar, regresaban a casa por considerar perdido el día. Existen leyendas de viudas y apariciones en la noche de Difuntos.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15022','misterio','Misterios de Cedeira','En sus montes y acantilados vivían, según la tradición, las meigas. Es uno de los enclaves gallegos donde más persiste la cultura de la brujería costera.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27020','misterio','Misterios de Friol','La Cova da Serpe es escenario de una de las leyendas más famosas de Galicia: una serpiente gigante que devoraba ganado y exigía sacrificios hasta que un caballero la venció con una lanza bendita.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('36014','misterio','Misterios de Tui','Considerada una de las "ciudades donde viven las brujas de Galicia". Su pasado judío y su posición fronteriza han generado un sustrato de leyendas de apariciones y prácticas esotéricas.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16078','misterio','Misterios de Cuenca','En la zona de Mangana se reunían antiguamente brujas en secreto. La Casa de la Sirena es protagonista de una de las leyendas más inquietantes de la ciudad, ambientada en sus calles oscuras y tortuosas.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16135','misterio','Misterios de Moya','Uno de los pueblos abandonados más impresionantes de España, frecuentado por amantes del misterio y la fotografía de ruinas.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16033','misterio','Misterios de Belmonte','Considerado uno de los castillos más embrujados de España. Muchos visitantes aseguran haber vivido sucesos paranormales en sus estancias.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('02010','misterio','Misterios de Chinchilla de Montearagón','Sus cuevas subterráneas, el barrio árabe y su conjunto histórico amurallado son escenario de leyendas y rutas de misterio que recorren sus callejas medievales.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45168','misterio','Misterios de Toledo','Posiblemente la ciudad con más rutas de misterio nocturnas de España. Sus calles estrechas y oscuras guardan apariciones reportadas en la Casa de las Cabezas, el Castillo de San Servando y el barrio judío. Existen tours específicos "Toledo Siniestro".','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17220','misterio','Misterios de Viladrau','Cuna de las célebres "Brujas de Viladrau", perseguidas en el juicio de brujería de 1618-1622. La ermita de Sant Segimon era el punto de reunión de los aquelarres la noche de Todos los Santos.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08212','misterio','Misterios de Sant Feliu Sasserra','Sede de los juicios por brujería de la Catalunya central. Su museo narra la persecución, tortura y muerte de las mujeres condenadas por brujería, con un montaje multimedia basado en hechos reales.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('43169','misterio','Misterios de Vilaplana','La Mussara, pedanía despoblada en los años 60, lleva más de 100 años con un misterio sin resolver. Se reportan fenómenos paranormales, apariciones y ruidos inexplicables entre sus ruinas; se ha comparado con el pueblo de "Stranger Things".','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10060','misterio','Misterios de Castañar de Ibor','La tradición oral mantiene viva la existencia de brujas en los Ibores, con testimonios recogidos por la Inquisición en la comarca. Es uno de los puntos de brujería documentada de Extremadura.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10102','misterio','Misterios de Ibahernando','La Cueva de las Brujas de Ibahernando es un lugar donde "la imaginación se despierta sola", según los lugareños, asociado a leyendas de aquelarres y rituales.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10067','misterio','Misterios de Coria','El ex-convento de San Francisco en ruinas es uno de los lugares más inquietantes de Extremadura, frecuentado por amantes del turismo oscuro.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12141','misterio','Misterios de Zorita del Maestrazgo','Uno de los centros de peregrinación más misteriosos de España. Hasta el siglo XX acudían "endemoniados" para ser exorcizados en el santuario, con testimonios documentados de posesiones y rituales de liberación.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('30015','misterio','Misterios de Caravaca de la Cruz','La leyenda de la Vera Cruz (lignum crucis que apareció milagrosamente en 1231) y la tradición templaria del lugar generan una oferta de rutas de misterio ("Caravaca Misteriosa") donde se narra la doble vela a Dios y al Diablo de los caballeros caídos.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('30035','misterio','Misterios de San Javier / Los Alcázares','La Isla del Barón, en el Mar Menor, es escenario de la leyenda de una aparición femenina la noche de San Juan. Los pescadores relatan haber visto a una mujer de extraordinaria belleza envuelta en un resplandor.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31135','misterio','Misterios de Javier','Cuna de San Francisco Javier. Sus estancias centenarias y su posición defensiva entre reinos han generado leyendas de apariciones y ruidos inexplicables, muy frecuentadas en las Javieradas.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33013','misterio','Misterios de Olite','Una de las alas del palacio, hoy Parador, encierra la leyenda de un fantasma noble medieval. Se escuchan ruidos, lamentos y melodías de otros tiempos, especialmente en la Galería Dorada. Varios testimonios avalan el paseo del espectro del rey Carlos III.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90717','misterio','Misterios de Ansoáin / Pamplona','Durante la Guerra Civil fue uno de los mayores campos de prisioneros. Murieron unos 750 presos, 231 de ellos en la fuga de mayo de 1938. El lugar es uno de los escenarios de turismo oscuro y parapsicología más visitados del norte.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('35027','misterio','Misterios de Teror','Lugar de la aparición de la Virgen del Pino (8 de septiembre de 1481), patrona de Gran Canaria. La imagen apareció en lo alto de un pino del que brotaba un manantial de aguas medicinales. Es el principal centro de peregrinación mística de la isla.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('07040','misterio','Misterios de Palma de Mallorca','Leyendas como el "drac de na Coca" (dragón que acechaba en las acequias de la ciudad) y relatos de brujería en el casco antiguo, heredados del pasado musulmán y medieval.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15089','misterio','Misterios de Es Vedrà','Considerado uno de los lugares con mayor concentración de energía telúrica del Mediterráneo. Leyendas de apariciones, sirenas y supuestos avistamientos de naves no identificadas. Es uno de los "tres vértices del triángulo de las Bermudas" según la tradición esotérica.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08009','misterio','Misterios de Cardona','La habitación 712 del Parador es uno de los lugares con fenómenos paranormales más documentados de España. Se escuchan ruidos, lamentos y melodías de otros tiempos. La leyenda atribuye la presencia al espíritu de Adalés, hija del vizconde Ramón Folch, encerrada por su padre en la torre tras enamorarse de un príncipe árabe; murió al año de reclusión. El perro del vigilante nocturno se negaba a pasar por la zona durante las obras de adaptación.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('43155','misterio','Misterios de Tortosa','El Parador de Tortosa, ubicado en un castillo musulmán del siglo X, figura entre los Paradores con mayor misterio de España. Se reportan fenómenos inexplicables, sombras y presencias en sus estancias y en las galerías subterráneas.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19257','misterio','Misterios de Sigüenza','El fantasma de doña Blanca de Borbón, esposa de Pedro I el Cruel, presuntamente envenenada entre estos muros en 1361. Huéspedes y empleados reportan sollozos, arrastrar de cadenas y una silueta difuminada recorriendo los pasillos abovedados. La Torre de Doña Blanca lleva su nombre.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('13002','misterio','Misterios de Almagro','Investigado por el programa Cuarto Milenio (Iker Jiménez y Carmen Porter). Empleadas y huéspedes reportan presencias, sillas que se giran solas y ruidos inexplicables. La habitación 39 es la más activa; varios huéspedes han abandonado el Parador tras vivencias paranormales.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26010','misterio','Misterios de León','La Catedral de León tiene documentados al menos cuatro fantasmas de personajes ilustres. El Parador de San Marcos, antiguo convento-hospital de peregrinos, cárcel (donde estuvo preso Quevedo) y prisión durante la Guerra Civil, es conocido por la aparición del "fantasma de Quevedo" y otras presencias en sus muros renacentistas.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26010','misterio','Casa de Aramberri / Casa de los Botines','León es conocida como "la ciudad de las almas en pena". Al menos cuatro fantasmas documentados en la Catedral, además del fantasma de Quevedo en San Marcos. La Casa Botines, obra de Gaudí, acumula leyendas y secretos.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37003','misterio','Misterios de Ciudad Rodrigo','Según la leyenda local, el espíritu de un noble traicionado y asesinado vaga por las murallas en noches de tormenta, vestido con armadura. Los visitantes reportan susurros y pasos en los pasillos vacíos del castillo.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40057','misterio','Misterios de Coca','La leyenda del "noble sin cabeza": Fernán Íñiguez de Coca, condenado por traición, vaga por sus pasillos de ladrillo. Se reportan fantasmas y secretos ocultos en sus gruesos muros.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40156','misterio','Misterios de Pedraza','Se dice que algunas noches se ven dos figuras espectrales vagando entre las murallas. La leyenda de Elvira y Roberto, amantes cuya historia terminó en tragedia, es la aparición más reportada; en noches de verano se ven sus sombras bajo una "aureola de fuego".','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34056','misterio','Misterios de Cervera de Pisuerga','Aunque el Parador moderno carece de la carga histórica de otros, la comarca montañesa palentina está llena de leyendas de ojáncanos y tradiciones celtas, y la zona es destino de retiros espirituales.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('11032','misterio','Misterios de Sanlúcar de Barrameda','El Castillo de Santiago ha sido investigado por equipos de parapsicología que han documentado fenómenos paranormales (psicofonías, imágenes y testimonios). Se realizan visitas especiales "Fenomenología paranormal en el Castillo de Santiago" donde se proyectan los audios e imágenes captados.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29067','misterio','Cortijo Jurado','Una de las casas encantadas más famosas de España. Entre 1890 y 1920 desaparecieron varias adolescentes en los alrededores; sus cuerpos aparecían junto al río Campanillas. La leyenda acusa a la familia Heredia de rituales satánicos. Se reportan gritos en la noche, túneles ocultos y apariciones.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29067','misterio','Casa de los Fantasmas / Gibralfaro','El "Caso de la Casa de los Fantasmas" de Málaga, un edificio levantado sobre un palacio señorial, ha saltado a los free tours por sus historias de misterio. La Torre del Homenaje del Castillo de Gibralfaro guarda la leyenda de una princesa encerrada por su padre.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29067','misterio','Alcazaba y Gibralfaro','Vigilantes han visto siluetas de personas paseando la Alcazaba que desaparecen sin dejar rastro. Leyenda de la princesa encerrada en la Torre del Homenaje de Gibralfaro.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29084','misterio','Misterios de Ronda','La Casa Rúa, en ruinas, es escenario de numerosas apariciones y fenómenos paranormales. La leyenda cuenta la desaparición misteriosa de una niña y el trágico hallazgo en la torre. Investigaciones paranormales han documentado sucesos.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('32002','misterio','Misterios de Antequera','El Dolmen de Menga, 1.000 años más antiguo que Stonehenge, sigue siendo un enigma arqueológico sin resolver. Su techo de bloque único y su orientación astronómica alimentan teorías esotéricas y lo convierten en un punto de energía.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41024','misterio','Misterios de Carmona','Analizada en el podcast "El Archivo del Misterio" por sus extrañas psicofonías. La Necrópolis romana, con tumbas tan impresionantes como la Tumba del Elefante y la de Servilia, es un foco de actividad paranormal documentada. En 2019 apareció un mausoleo romano en el patio de una vivienda particular.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16009','misterio','Misterios de Cádiz','El primer "ghost tour" sobre Cádiz paranormal recoge apariciones en la calle Mesón y el terrible suceso de 1755. Existe el enigma de la "niña" y la investigación de la calle Valcárcel, donde se sucedieron hechos luctuosos que propiciaron fenómenos insólitos.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23050','misterio','Castillo de Santa Catalina (Parador)','Único Parador de España con dos fantasmas documentados: Jasmina (espíritu de una mujer árabe, amante del alcaide) y el "Terrible Lagarto". Huéspedes reportan presencias y fenómenos inexplicables. Investigado por Cuarto Milenio.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06023','misterio','Misterios de Zafra','Visitado por Iker Jiménez en busca de sucesos paranormales. Los vecinos mayores recuerdan la aparición de un fantasma en los tejados del castillo zafrense en varias ocasiones a lo largo de los años.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46109','misterio','Misterios de Cheste','Uno de los lugares embrujados más famosos de la Comunidad Valenciana. Se han grabado múltiples psicofonías; los investigadores reportan lamentos de niños, rituales, pentagramas y un estruendo impresionante captado al poner un micrófono en el suelo. Investigado por Más Vale Sábado.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39040','misterio','Misterios de Isla de Pedrosa / Marina de Cudeyo','Considerada "la isla más paranormal de España". Lugar de aislamiento que acumula psicofonías aterradoras, sombras que se mueven entre las ruinas y el espectro de una misteriosa anciana con bata blanca. Numerosos investigadores han documentado actividad.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39040','misterio','Misterios de Marina de Cudeyo / Isla de Pedrosa','Considerada "la isla más paranormal de España". Psicofonías aterradoras, sombras entre las ruinas y el espectro de una anciana con bata blanca. Numerosos investigadores han documentado actividad.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39038','misterio','Misterios de Limpias','Tres presencias documentadas: Margarita de Eguilior (de 29 años, que toca el piano y pasea por las escaleras), su hija, y Antonio (antiguo sirviente). Predilección por la habitación 205. Se han obtenido fotografías con el rostro del Conde de Albox y de "Rosita" sosteniendo un bebé.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('21011','misterio','Misterios de Hondarribia','El Castillo de San Telmo (o de Higer), ligado al Parador, es protagonista de uno de los relatos más conocidos de fantasmas de Gipuzkoa. El Parador también acumula testimonios de presencias.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90689','misterio','Misterios de Gatika','Leyenda de la princesa mora cautiva que esperó en vano a su caballero y murió prisionera. Su espíritu vaga por los pasillos. El castillo tiene vínculos esotéricos documentados.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('48041','misterio','Misterios de Gautéguiz de Arteaga','Ligado a Eugenia de Montijo (emperatriz de Francia). Existe una "leyenda negra" que envuelve al castillo, frecuentado por amantes de lo esotérico.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05006','misterio','Misterios de Cangas del Narcea','El monasterio alberga restos arqueológicos de la estructura original y siglos de historia benedictina. Es uno de los Paradores con más testimonios de presencias.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05005','misterio','Misterios de Cangas de Onís','Leyenda de Don Pelayo, que murió enfrentándose a un oso en estos bosques. Los huéspedes reportan hojas que se mueven "por un viento que no existe" y la leyenda del oso.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('36002','misterio','Misterios de Baiona','La Torre del Príncipe inspiró a Alejandro Dumas para El hombre de la máscara de hierro. Leyendas de amantes prohibidos encerrados, del príncipe portugués Alfonso Enríquez y del Conde de Gondomar.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15078','misterio','Misterios de Santiago de Compostela','El Parador, antiguo hospital de peregrinos fundado por los Reyes Católicos en 1499, acumula leyendas de peregrinos fallecidos, apariciones marianas y meigas. Es final del Camino y centro de peregrinación mística.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15078','misterio','Hospital Psiquiátrico de Conxo','Lugar marcado por el sufrimiento de más de 1.200 pacientes en condiciones deplorables. Las imágenes de las celdas y pasillos abandonados son icono del turismo oscuro gallego.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22117','misterio','Misterios de Graus','El actual propietario asegura que el fantasma de la primera propietaria de la casa ronda las estancias, especialmente en determinadas fechas. La casa tiene capilla privada y mobiliario antiguo intacto.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26138','misterio','Misterios de Santo Domingo de la Calzada','El milagro del gallo y la gallina: un joven peregrino alemán, Hugonell, fue injustamente ahorcado y, cuando sus padres fueron a buscarlo, este seguía vivo milagrosamente mientras un gallo asado cantaba. Es Bien de Interés Cultural inmaterial y uno de los misterios más famosos del Camino.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18151','misterio','Misterios de Pampaneira / Bubión / Capileira','La tradición oral alpujarreña conserva leyendas de brujería heredadas de la repoblación con gallegos (que trajeron el culto a las meigas), rituales de fertilidad y apariciones en los barrancos.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18157','misterio','Misterios de Pinos Genil','La "Vieja del Blanqueo" forma parte de la tradición oral del municipio, vinculada a la antigua fábrica de blanqueo de papel (dirigida por Berta Wilhelmi) y al patrimonio industrial abandonado de la zona. Las ruinas de la fábrica y los paseos de la central eléctrica (incluidos en rutas como "Los Misterios de Pinos Genil" de Secretos de Granada) generan relatos de presencias y ecos del pasado industrial. La documentación escrita sobre la aparición es escasa, por lo que se mantiene como leyenda oral local.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90429','misterio','Misterios de Alfacar','Lugar del fusilamiento de Federico García Lorca (agosto 1936). La Fuente Grande, manantial árabe que abastecía la Alhambra, es uno de los últimos reductos musulmanes en capitular (1491). El entorno está cargado de la energía del Barranco de Víznar y de la "no-muerte" de Lorca (leyenda del panadero que lo encontró malherido).','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18189','misterio','Misterios de Víznar','Más de 6.500 personas enterradas en fosas comunes en el barranco. Las exhumaciones continúan. Es uno de los escenarios de turismo oscuro más simbólicos de España.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29094','misterio','Misterios de Vélez-Málaga','El hombre sin rostro de la Casa Cervantes. Testigos han visto una figura etérea masculina sin rostro que vaga y desaparece. La historia trágica: hace más de 200 años un hombre cayó al pozo del patio, murió ahogado y su rostro quedó tan deformado que lo taparon con una sábana. También se reportan avistamientos OVNI y procesos de la Inquisición.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23055','misterio','Misterios de Linares','Trompetas del Apocalipsis y caso de ouija con intervención de la Policía Nacional. Dos mujeres y una menor se comunicaron con el espíritu de un niño llamado Agustín (patrón de la ciudad); cuadros y radiadores se movían solos. La situación fue tan alarmante que requirió la intervención policial.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24006','misterio','Misterios de Arjona','Maldición del callejón de las Brujas. María Santiago Rabadán, juzgada por hechicería en un Auto de Fe en 1655. Investigado por Manuel Jesús Segado Uceda.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23092','misterio','Misterios de Úbeda','Leyenda del Señor de las Cadenas, la Dama de la Capa y el origen de la expresión "irse por los cerros de Úbeda". La Puerta de Granada oculta un tesoro medieval junto a la muralla árabe. La Casa de los Salvajes acumula relatos inquietantes.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19130','misterio','Molino de la Fábrica de Paños / Alcázar Real','La provincia de Guadalajara, además del famoso Parador de Sigüenza (doña Blanca), acumula leyendas como el Alcázar Real, el Molino de la Fábrica de Paños y el fantasma de la Casa de la Condesa. Recopilados por investigadores como Miguel Linares.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10049','misterio','Misterios de Casar de Cáceres / Arroyo de la Luz','La Dama Blanca que aparece sentada en noches de tormenta en la carretera Casar de Cáceres-Arroyo de la Luz. Es una de las apariciones en cunetas extremeñas más conocidas.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10123','misterio','Misterios de Mirabel','El hombre alto vestido de negro que continúa suicidándose en la curva de Mirabel. Una de las apariciones de carretera más escalofriantes de Extremadura.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10121','misterio','Misterios de Miajadas','La dama de rojo de Miajadas, aparición en cuneta.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10140','misterio','Misterios de Peraleda de la Mata','La niña vestida de comunión que se acerca a los coches en la carretera de Peraleda de la Mata.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10127','misterio','Misterios de Montehermoso / Pozuelo de Zarzón','La joven de la recta de la carretera Montehermoso-Pozuelo de Zarzón.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08094','misterio','Colegio José Hurtado (Realejo)','Conocido como el "colegio fantasma de Granada", investigado por Cuarto Milenio.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08094','misterio','Barrio del Albaicín (ruta general)','Diversas "casas del miedo" y casas encantadas repartidas por el barrio. Daniel Maya incluye ruta específica.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08094','misterio','Bosque de la Alhambra (ruta nocturna)','Ruta "Enigmas y Leyendas del Bosque de la Alhambra" de Daniel Maya: asesinatos marcados por la luna llena, apariciones de personajes históricos y escritores famosos, fenómenos paranormales en enclaves centenarios.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42174','misterio','Misterios de Sotillo del Rincón','El misterio del reloj maldito y el pueblo poseído por el diablo. Un extraño suceso con el reloj del pueblo desencadenó una serie de muertes misteriosas. Inspiró el libro "La rebelión de Lucifer" de J.J. Benítez. Recogido por el programa Palacios y Castillos con Misterio de CyLTV.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('02047','misterio','Misterios de Masegoso','El fantasma de Masegoso. El pueblo, rico y floreciente, desapareció tras el odio irreconciliable entre dos poderosas familias (Julián Alvarez y Andrés Orozco). Leyenda de desaparición misteriosa de un pueblo entero.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37006','misterio','Misterios de Ledesma','La antigua Bletisa romana acumula leyendas medievales entre sus calles y murallas, en una de las zonas más mágicas de la provincia.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37001','misterio','Misterios de Candelario','Pueblo de montaña con tradiciones y leyendas ancestrales, en una de las sierras más mágicas de Salamanca.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37005','misterio','Misterios de La Alberca','Pueblo mágico por excelencia de Las Batuecas, con tradiciones seculares, leyendas de brujería serrana y ermitas rupestres en el valle.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('49166','misterio','Misterios de Puebla de Sanabria','Cabecera de la comarca de Sanabria, tierra de meigas, conjuros, mal de ojo y el "llobu". Cerca del Lago de Sanabria con su leyenda de Valverde de Lucerna (pueblo sumergido cuyas campanas suenan la noche de San Juan).','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('49065','misterio','Misterios de Fermoselle','Cuenta con ruta nocturna oficial "Mitos y Leyendas" organizada por el Ayuntamiento, que recorre los secretos que esconde la villa cuando cae la noche.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('49219','misterio','Misterios de Toro','El misterio de la Calle Balborraz: un capitán musulmán que quería destruir la ciudad, una ejecución y una historia de amor. Se cruza con la leyenda de la "Cabeza de Piedra" de la Catedral.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09011','misterio','Misterios de Oña','El misterio del fauno burgalés: en el Jardín Secreto se esconde la escultura de un fauno petrificado por una maldición, guardian de los seres mágicos del bosque. Entrada libre.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09007','misterio','Misterios de Frías','Una de las ciudades más pequeñas de España, con un castillo que acumula leyendas desde el siglo X.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09014','misterio','Misterios de Poza de la Sal','Una de las Raíces de Castilla, con un patrimonio cargado de historia y leyendas en el norte de Burgos.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09008','misterio','Misterios de Lerma','Villa ducal con un pasado cargado de intrigas palaciegas y leyendas entre sus conventos.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09005','misterio','Misterios de Covarrubias','Una de las Raíces de Castilla, con un casco histórico que guarda leyendas desde los orígenes del condado.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('47085','misterio','Misterios de Medina del Campo','La Dama de la Mota y la maldición del castillo. La reina Isabel lo utilizó como residencia y prisión política; varios personajes fueron ejecutados por mandato real entre sus muros. Es uno de los castillos más temidos de Castilla.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90805','misterio','Misterios de Antigüedad','Uno de los municipios palentinos que más misterios alberga: se habla de energías milenarias, una sociedad intraterrestre y avistamiento de objetos luminosos no identificados en el cielo. Considerado "lugar de poder".','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34199','misterio','Misterios de Velilla del Río Carrión','La leyenda dice que Plinio el Viejo mencionó estas fuentes. La zona está cargada de historia y tradiciones ancestrales.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('14001','misterio','Misterios de Alarcón','Peñasco estratégico con un casco histórico cargado de leyendas medievales, en uno de los pueblos más singulares de la provincia de Cuenca.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16112','misterio','Misterios de Huete','Antigua ciudad romana y medieval, con un patrimonio cargado de leyendas y tradiciones.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16170','misterio','Misterios de Priego','Uno de los pueblos más bonitos de la provincia, en un paraje natural escénico que acumula tradiciones y leyendas.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19212','misterio','Misterios de Pastrana','En el corazón de la Alcarria, Pastrana ofrece "historia, conventos y leyendas" del Siglo de Oro, con la figura maldita de la princesa de Éboli.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19044','misterio','Misterios de Atienza','Villa medieval con un patrimonio cargado de leyendas de caballeros y tradiciones ancestrales.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19190','misterio','Misterios de Molina de Aragón','Enclave brujeril documentado. Las brujas de Molina se trasladaban hipotéticamente hasta Gallocanta (Zaragoza) para un aquelarre. Una tal Águeda, del siglo XVI, declaró que su abuela había sido bruja y se reunía en Gallocanta.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19211','misterio','Misterios de Pareja','Objeto del libro "Alcarria bruja. Historia de la hechicería en Guadalajara y los procesos de la villa de Pareja", de Javier Fernández Ortea. Procesos de brujería documentados.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45165','misterio','Misterios de Talavera de la Reina','Acumula leyendas y tradiciones populares de la provincia de Toledo, con un sustrato de misterios recogidos por José Talavera.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45125','misterio','Misterios de Oropesa','Villa medieval con un castillo que acumula leyendas de nobles y tradiciones, en una de las zonas más mágicas de la provincia de Toledo.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45200','misterio','Misterios de Los Yébenes','Zona conocida por las leyendas de los monjes sobrenaturales, recogidas en el libro de mitos y leyendas de Castilla-La Mancha.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90825','misterio','Misterios de Almadén','Las minas de Almadén son escenario de la leyenda del Morgo, duende minero que extrae minerales bajo tierra. Tradiciones de brujería y apariciones en una de las comarcas más enigmáticas de CLM.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('13013','misterio','Misterios de Puertollano','Cuenta con leyendas de fantasmas locales, recogidas en rutas y tradiciones orales.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('13018','misterio','Misterios de Valdepeñas','La mano negra, el morgo y los fantasmas de Valdepeñas son algunos de sus mitos y leyendas más conocidos.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('02030','misterio','Misterios de Yeste','Uno de los pueblos con castillo más impresionantes de Albacete, con historia y leyendas de la Sierra del Segura.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('02005','misterio','Misterios de Almansa','Una de las fortalezas más impresionantes de Albacete, con historia y leyendas asociadas a la famosa batalla.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('02004','misterio','Misterios de Alcaraz','Uno de los pueblos más bonitos de Albacete, con historia medieval y leyendas.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50117','misterio','Misterios de Gallocanta','Centro de aquelarres de toda Aragón. Las brujas de la zona se reunían en la laguna, con leyendas de hechicería que recorren la zona desde hace siglos. Las brujas de Molina de Aragón se desplazaban hasta aquí.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44158','misterio','Misterios de Mora de Rubielos','Comparte nombre con Rubielos de Mora por una leyenda de amor que explica por qué ambos pueblos tienen el mismo nombre invertido.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44201','misterio','Misterios de Rubielos de Mora','La otra mitad de la leyenda de amor que da nombre a ambos pueblos. calles empedradas y un pasado medieval cargado de historia.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22028','misterio','Misterios de Ansó','Pueblo del Pirineo con chimeneas de brujas y tradiciones mágicas, en un entorno de naturaleza salvaje donde prosperan las leyendas.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31105','misterio','Misterios de Fitero','La Cueva de la Mora de Fitero, lugar mágico que cautivó al mismísimo Gustavo Adolfo Bécquer. Es una de las rutas con leyenda más señaladas de Navarra.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10082','misterio','Misterios de Garrovillas de Alconétar','Uno de los pueblos más misteriosos de Extremadura: duendes, diablos, brujas, monaguillos muertos, pasadizos secretos, sirenas malditas, princesas encantadas, tesoros ocultos y caníbales. La Sirena de Garrovillas y las brujas (entre ellas La Macharra) que salen los sábados por las chimeneas montadas en escobas. La "Ventana del Diablo" de la iglesia de San Pedro.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10195','misterio','Misterios de Trujillo','Villa monumental con un casco histórico que acumula leyendas desde la Reconquista, en una de las zonas más mágicas de Extremadura.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10148','misterio','Misterios de Plasencia','Ciudad medieval con un casco histórico cargado de leyendas y tradiciones.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90838','misterio','Misterios de Barcarrota','Aquelarre anual teatralizado basado en los archivos inquisitoriales. Las brujas La Corbacha y La Candelera, famosas en los autos de fe de la Inquisición.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06014','misterio','Misterios de Jerez de los Caballeros','Una de las ciudades templarias del sur de Badajoz, con tradiciones y leyendas medievales.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06010','misterio','Misterios de Fregenal de la Sierra','Ciudad templaria con un castillo del siglo XVI y tradiciones de misterio, además de un enclave de astroturismo.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06015','misterio','Misterios de Llerena','Pueblo señorial con un pasado ligado a la Inquisición, que acumula tradiciones y leyendas.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('14049','misterio','Misterios de Palma del Río','La dama fantasmal de Santa Clara. Los vecinos hablan de una figura blanca femenina que se pasea entre lamentos en el convento. El origen sería un macabro suceso de finales del siglo XV, recogido por el cronista fray Andrés de Guadalupe.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('14075','misterio','Misterios de Zuheros','Uno de los pueblos blancos más bonitos de Córdoba, con un castillo colgado sobre la sierra que acumula leyendas.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('14055','misterio','Misterios de Priego de Córdoba','Hogar de relatos misteriosos y tradiciones que han capturado la imaginación de sus habitantes.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41068','misterio','Misterios de Osuna','Uno de los municipios sevillanos con más historia y tradiciones, recogidas por National Geographic.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41039','misterio','Misterios de Écija','Municipio sevillano con tradiciones únicas y un "estilo ecijano" cargado de leyendas.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41095','misterio','Misterios de Utrera','Municipio sevillano con imaginería antigua y tradiciones únicas que acumulan leyendas.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41036','misterio','Misterios de El Coronil','La estación encantada de El Coronil, epicentro de fenómenos paranormales en la campiña sevillana. Voces extrañas, sombras que cruzan de una habitación a otra y esferas luminosas en medio de la noche. Recogido por ABC Sevilla.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23028','misterio','Misterios de Cazorla','El Cortijo de las Ánimas, pueblo fantasma engullido por la presa del pantano del Tranco. La leyenda cuenta que José Requena Carmona tuvo un encuentro con el mismísimo Satanás.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18089','misterio','Misterios de Guadix','Ciudad con un barrio troglodita y un pasado árabe que acumula leyendas de brujería y apariciones.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19001','misterio','Misterios de Alhama de Granada','Enclave con poderes curativos desde época romana y árabe, en un paraje de tajos impresionantes que acumulan tradiciones y leyendas.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18135','misterio','Misterios de Montefrío','Uno de los pueblos más bonitos de Granada, con un pasado nazarí cargado de leyendas.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('11023','misterio','Misterios de Medina Sidonia','"Pura historia de Cádiz", fundado por fenicios. Acumula leyendas de brujería y apariciones arraigadas en la cultura popular de la región.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('11039','misterio','Misterios de Vejer de la Frontera','Municipio cargado de leyendas, con cuaderno de campo "Historias y Leyendas" editado por su turismo.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('11035','misterio','Misterios de Tarifa','Historia heroica de Tarifa y leyendas medievales, con un pasado estratégico cargado de tradiciones.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('04017','misterio','Misterios de Níjar','Historia milenaria desde la prehistoria, con huella de fenicios, íberos, cartagineses, romanos y árabes que dejaron vestigios y leyendas.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90859','misterio','Misterios de Fontilles / El Verger','La Dama Rosa, fantasma de una mujer que murió dando a luz a su hijo en el sanatorio. Sus llantos se escuchan entre las instalaciones abandonadas, que atendieron a casi 3.000 personas.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03002','misterio','Misterios de Alcoy','El "crimen de les Mananes" (1915), tema tabú en Alcoy. Tres curanderas/hechiceras/brujas (dos hermanas y una cuñada) con supuestos poderes sobrenaturales se relacionaron con la desaparición y hallazgo del cuerpo de un niño en una acequia.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03040','misterio','Misterios de Villena','Acumula mitos, leyendas y tradiciones como las Voces del Pasado, en una de las zonas más mágicas de Alicante.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45017','misterio','Misterios de Xàtiva','Túneles secretos bajo el Castillo de Xàtiva, donde el misterio y la historia se entrelazan. Leyendas de los papas Borgia y curiosidades enigmáticas del Hotel Montsant.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46182','misterio','Misterios de Olocau','Leyenda cidiana: el castillo se conquistó de noche con un rebaño de cabras con velas encendidas en los cuernos, que hicieron creer a los musulmanes que un gran ejército les atacaba.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12128','misterio','Misterios de Vilafamés','Uno de los pueblos más bonitos de Castellón, con magia de piedra y un pasado medieval cargado de leyendas.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12051','misterio','Misterios de Culla','Considerado el "último pueblo templario de España", con un pasado cargado de misterio y tradiciones medievales.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('43118','misterio','Misterios de Pratdip','Pueblo con calles dedicadas a las brujas. Leyenda del Dip, criatura misteriosa, y de los perros diabólicos que atacaban a los vecinos. Ruta oficial del Dip.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25059','misterio','Misterios de Bossòst','Leyenda de las siete ermitas (seis más la iglesia) que debían construirse para proteger al pueblo de la peste, tras el encuentro de un pastor con un monje ermitaño.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18002','misterio','Misterios de Besalú','Uno de los conjuntos medievales mejor conservados de Cataluña, con un barrio judío que acumula leyendas y un pasado cargado de historia.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90889','misterio','Misterios de Castelló d''Empúries','Villa medieval con un centro histórico que conserva el encanto del pasado, con leyendas y tradiciones.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28131','misterio','Misterios de San Lorenzo de El Escorial','"Octava Maravilla del Mundo" y uno de los edificios más enigmáticos de España. Considerado "una puerta al infierno que Felipe II se encargó de sellar". Curaciones milagrosas, movimientos del Sol, estigmatizaciones y una leyenda local sobre una mina cuyas galerías llegaban al infierno.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28027','misterio','Misterios de Buitrago de Lozoya','Pueblo medieval de cuento de la sierra de Madrid, con una muralla almenada y un centro urbano cargado de leyendas.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28052','misterio','Misterios de Chinchón','Uno de los pueblos medievales más bonitos de Madrid, con una plaza mayor única y tradiciones centenarias.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28082','misterio','Misterios de Manzanares el Real','Castillo medieval de la sierra de Madrid que acumula leyendas de nobles y tradiciones.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39024','misterio','Misterios de Comillas','Free tour oficial de "Misterios y leyendas de Comillas": milagros, sonidos escalofriantes y extrañas apariciones, historias transmitidas de generación en generación.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39067','misterio','Misterios de Ruesga','La leyenda de "La Loba de Ruesga". María Ruiz fue acusada de brujería y de la desaparición de niños, juzgada y condenada a la hoguera. Se dice que su espíritu sigue vagando por el pueblo y se le atribuyen fenómenos paranormales. Basada en un evento histórico real.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39080','misterio','Misterios de San Vicente de la Barquera','Pueblo con historias y leyendas recogidas en rutas oficiales.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90013','misterio','Misterios de Castropol','La xana de la cascada del Cioyo, una de las historias más tristes de las xanas asturianas.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33043','misterio','Misterios de Onís','Leyendas del diablo burlón, un personaje benigno que toma presencia humana o animal y disfruta riéndose de la gente. Recopiladas por Aurelio de Llano.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('36004','misterio','Misterios de Cambados','Torre medieval defensiva contra vikingos, en una zona de tradiciones mágicas y meigas.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('36005','misterio','Misterios de Cangas','El Bosque Encantado de Aldán, con restos de un minúsculo castillo inacabado con foso y almenas.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34002','misterio','Misterios de Allariz','Uno de los pueblos más bonitos de Ourense, con un casco medieval cargado de leyendas.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34004','misterio','Misterios de Celanova','La capilla mozárabe de San Miguel, joya del año 937, guarda tradiciones y leyendas ancestrales en uno de los conjuntos más místicos de Galicia.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('32069','misterio','Misterios de Ribadavia','Leyenda del puente construido por Santo Telmo (patrón de los marineros), que predicó ante una multitud y dividió las nubes en dos. Judería con tradiciones seculares.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34003','misterio','Misterios de Castro Caldelas','Uno de los pueblos más bonitos de Ourense, con un castillo que acumula leyendas sobre el Sil y la Ribeira Sacra.','inventario_misterioso_pdf');
